#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Write own bilingual E7 assessment specifications; no learner observations."""
from pathlib import Path
from datetime import datetime,timezone
import copy,json
ROOT=Path.cwd();OWN=Path(__file__).resolve().parent;REL=OWN.relative_to(ROOT).as_posix();meta=json.loads((OWN/'prospective-paths.json').read_text());ISO=Path(meta['isolationRoot']);IDS=meta['goalIds']
def both(name,x):
 for base in [OWN,ISO/REL]:(base/name).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def expect(id,ed,ee,od,oe):return dict(id=id,essentialUnderstandingDe=ed,essentialUnderstandingEn=ee,observablePerformanceDe=od,observablePerformanceEn=oe)
def axis(id,de,en):return dict(id=id,textDe=de,textEn=en)
def case(id,td,te,pd,pe,fd,fe):return dict(id=id,taskDemandDe=td,taskDemandEn=te,expectedPerformanceDe=pd,expectedPerformanceEn=pe,understandingFocusDe=fd,understandingFocusEn=fe)
def profile(archetype,ex,axes,cases):return dict(archetype=archetype,expectations=ex,coverageExpectations=dict(requiredExpectationIds=[x['id'] for x in ex],alternativeExpectationGroups=[],minimumIndependentDemonstrations=2,freshVariationRequired=True,independentTransferRequired=True),variationAxes=axes,applicationCaseBriefs=cases)
profiles=[]
profiles.append(profile('modeling',[
 expect('animal-development-interplay','Zellteilung erzeugt weitere Zellen, Differenzierung verändert ihre Spezialisierung und Morphogenese ihre räumliche Anordnung beziehungsweise Gewebeform. Die drei Vorgänge greifen bei Tierentwicklung ineinander; eine größere Zellzahl allein belegt noch keine neue Organform.','Cell division produces additional cells, differentiation changes specialization, and morphogenesis changes spatial organization or tissue shape. These processes interact in animal development; more cells alone do not establish a new organ shape.','Die lernende Person beschreibt das Zusammenspiel an einer neuen materialgestützten Tierentwicklung und ordnet Veränderungen der Zellzahl, Zellfunktion und Gewebeform begründet zu.','The learner describes the interplay in a fresh material-supported animal development case and justifies which changes concern cell number, cell function and tissue shape.')],
 [axis('development-display','Zeitfolge, Querschnitt und Veränderungen unter einem gegebenen Eingriff vergleichen.','Compare a time sequence, a cross-section and changes under a supplied intervention.'),axis('number-function-shape','Zellzunahme, Spezialisierung und Formänderung getrennt beobachten und miteinander verbinden.','Observe cell increase, specialization and shape change separately and connect them.')],[
 case('folding-animal-tissue','Ein frisches Tierentwicklungsmodell zeigt zunächst 40 ähnliche Zellen, später 80 Zellen mit zwei durch Funktionshinweise unterschiedenen Zellgruppen und schließlich eine gefaltete Gewebeschicht bei weiterhin 80 Zellen. Beschreibe, wie Teilung, Differenzierung und Morphogenese zusammenwirken. Was zeigt die letzte Formänderung über das Verhältnis von Zellzahl und Gewebeform?','A fresh animal development model first shows 40 similar cells, then 80 cells with two groups distinguished by supplied function clues, and finally a folded tissue sheet still containing 80 cells. Describe how division, differentiation and morphogenesis interact. What does the final shape change show about cell number and tissue shape?','Die Zellzunahme wird der Teilung, die unterschiedlichen Funktionen der Differenzierung und die Faltung der Morphogenese zugeordnet. Die lernende Person beschreibt einen zusammenhängenden Entwicklungsprozess und erklärt, dass Formänderung nicht allein durch weitere Teilung entstehen muss. Farben sind Modellkennzeichen, keine Abstammungsbeweise.','Cell increase is assigned to division, different functions to differentiation and folding to morphogenesis. The learner describes a coherent developmental process and explains that shape change need not result solely from further division. Colors are model markers, not lineage evidence.','Drei Prozesse als Teile einer Entwicklung statt als bloße Begriffsfolge beschreiben.','Describe three processes as parts of one development rather than merely listing terms.'),
 case('animal-shape-control','Eine andere gegebene Tiergewebereihe zeigt in Kontrolle und Eingriff gleich viele Zellen mit denselben im Material nachgewiesenen Spezialisierungen. Nur im Eingriff bleibt die sonst sichtbare Einfaltung aus; laut Material wird dort die Zellformänderung vorübergehend gestört. Beschreibe das Zusammenspiel und begründe, welche Entwicklungsleistung verändert und welche nicht allein widerlegt ist.','A different supplied animal tissue sequence shows equal cell numbers and the same material-established specializations in control and intervention. Only the intervention lacks the usual fold; the material states that cell shape change is temporarily disrupted. Describe the interplay and justify which developmental outcome is changed and which is not disproved by this observation alone.','Die lernende Person erklärt die gestörte räumliche Formbildung bei erhaltener Zellzahl und Spezialisierung. Sie behauptet weder ausgefallene Teilung noch fehlende Differenzierung und begrenzt die Schlussfolgerung auf den beschriebenen Modellprozess.','The learner explains disrupted spatial shaping despite preserved cell number and specialization. Neither failed division nor absent differentiation is claimed; the conclusion is limited to the supplied model process.','Frischer Transfer auf getrennt kontrollierte Entwicklungsaspekte.','Fresh transfer to separately controlled aspects of development.')]))
profiles.append(profile('modeling',[
 expect('plant-development-interplay','Pflanzliche Entwicklung verbindet Zellteilung mit anschließender Spezialisierung, Wachstum und räumlicher Organisation. Neue Gewebe oder Organe entstehen nicht allein durch Vergrößerung schon vorhandener Zellen. Ein gegebenes Sprossmodell ist kein universeller Ablauf jeder Pflanzenentwicklung.','Plant development connects cell division with subsequent specialization, growth and spatial organization. New tissues or organs do not arise solely by enlarging existing cells. A supplied shoot model is not a universal sequence for all plant development.','Die lernende Person erläutert in zwei neuen Pflanzenentwicklungsfällen, welche Befunde Teilung, Differenzierung und Morphogenese stützen und wie diese Vorgänge zusammen ein Organ ausbilden.','The learner explains in two fresh plant development cases which observations support division, differentiation and morphogenesis and how these processes together form an organ.')],
 [axis('plant-organ','Blattbildung am Spross und materialgestützte Fruchtentwicklung vergleichen.','Compare leaf formation at a shoot and material-supported fruit development.'),axis('development-evidence','Zellzahlen, Funktionshinweise und Organquerschnitte statt bloßer Größenzunahme verwenden.','Use cell counts, function clues and organ sections rather than size increase alone.')],[
 case('new-leaf-sequence','Eine neue Sprossreihe liefert Zellzahlen, Gewebequerschnitte und Hinweise auf später photosynthetisch beziehungsweise leitend spezialisierte Zellen. Aus einer kleinen Ausbuchtung entsteht ein Blatt. Erläutere das Zusammenwirken von Teilung, Differenzierung und Morphogenese und begründe, warum ein größerer Spross allein nicht alle drei Vorgänge nachweist.','A fresh shoot sequence supplies cell counts, tissue sections and clues identifying later photosynthetic and conducting cells. A leaf develops from a small protrusion. Explain the interplay of division, differentiation and morphogenesis and why a larger shoot alone does not demonstrate all three processes.','Zellzahlzunahme, spezialisierte Gewebefunktionen und Blattgestalt werden mit den drei Vorgängen verbunden. Ihre zeitliche und räumliche Zusammenarbeit wird erklärt; aus Größe oder Modellfarbe allein wird keine Differenzierung erschlossen.','Cell number increase, specialized tissue functions and leaf shape are connected with the three processes. Their temporal and spatial interaction is explained; size or model color alone does not establish differentiation.','Entwicklungsmechanismen am neuen Pflanzenorgan erklären.','Explain developmental processes in a fresh plant organ.'),
 case('fruit-tissue-variation','Ein anderer materialgestützter Fall zeigt die Entwicklung einer Frucht: zunächst nehmen die Zellzahlen in einer Region zu, später werden Speichergewebe und Schutzgewebe durch Funktionsdaten unterschieden, zugleich verändert sich die Organform. Eine Vergleichsreihe zeigt nur größere Zellen ohne zusätzliche Zellzahl. Erläutere beide Reihen und die Grenze der Behauptung, Pflanzenentwicklung sei nur Zellteilung.','A different material-supported case shows fruit development: cell numbers first increase in one region, later storage and protective tissues are distinguished by function data while organ shape changes. A comparison sequence shows only larger cells without increased cell number. Explain both sequences and the limits of claiming that plant development is only cell division.','Die lernende Person verbindet die Entstehung und Organisation unterschiedlicher Fruchtgewebe mit Differenzierung und Morphogenese sowie Teilung. Zellvergrößerung wird von Teilung unterschieden. Der Fall belegt einen gegebenen Entwicklungsweg, nicht die vollständige Fortpflanzung, Fruchtverbreitung oder alle Pflanzenarten.','The learner connects the formation and organization of different fruit tissues with differentiation and morphogenesis as well as division. Cell enlargement is distinguished from division. The case supports one supplied developmental pathway, not complete reproduction, fruit dispersal or all plant species.','Frischer Transfer über ein anderes Organ und einen Größen-Gegenfall.','Fresh transfer through a different organ and a size counterexample.')]))
profiles.append(profile('modeling',[
 expect('meristem-signal-regulation','Meristeme enthalten teilungsfähige Zellen und liefern Zellen für das Pflanzenwachstum. Signalaustausch zwischen Zellen kann Teilung und Entwicklung räumlich koordinieren; Empfangen eines Signals und die nachfolgende Zellreaktion sind verschiedene Schritte. Nicht jede Pflanzenzelle ist ein Meristem und nicht jedes Signal löst Teilung aus.','Meristems contain cells capable of division and supply cells for plant growth. Cell-to-cell signaling can coordinate division and development spatially; receiving a signal and the subsequent cellular response are distinct steps. Not every plant cell is a meristem and not every signal triggers division.','Die lernende Person erklärt an gegebenen Meristemfällen, wie teilungsfähige Zellen und ein beschriebenes Signalsystem zusammen Wachstum organisieren, und begrenzt Schlussfolgerungen zu Sender, Empfänger und Reaktion.','The learner explains in supplied meristem cases how dividing cells and a described signaling system together organize growth and bounds conclusions about sender, receiver and response.')],
 [axis('meristem-position','Spross- und Wurzelspitze mit ausdrücklich gegebenen Zell- und Signalhinweisen nutzen.','Use shoot and root tips with explicitly supplied cell and signaling information.'),axis('signal-step','Signalangebot, Empfang und nachfolgende Reaktion getrennt variieren.','Vary signal supply, reception and subsequent response separately.')],[
 case('shoot-tip-signal','Ein neues Sprossmodell markiert durch Beobachtungen teilungsaktive Meristemzellen und benachbarte differenzierte Zellen. Laut Material sendet eine Zellgruppe ein Signal; eine Empfängergruppe verändert darauf ihre Teilungsrate. Erkläre die Bedeutung des Meristems und den Beitrag dieses Signalaustauschs zum geordneten Wachstum.','A fresh shoot model uses observations to identify actively dividing meristem cells and neighboring differentiated cells. The material states that one cell group sends a signal and a receiving group changes its division rate. Explain the role of the meristem and how this signaling contributes to organized growth.','Die lernende Person erklärt Zellbereitstellung durch das Meristem und lokale Koordination der beschriebenen Teilungsreaktion. Sender, Empfänger und Reaktion werden unterschieden. Sie erfindet keinen bestimmten Signalstoff oder Transportweg und hält differenzierte Nachbarzellen nicht allein aufgrund ihrer Nähe für Meristemzellen.','The learner explains cell supply by the meristem and local coordination of the stated division response. Sender, receiver and response are distinguished. No specific signal molecule or transport pathway is invented; proximity alone does not identify neighboring differentiated cells as meristem cells.','Meristemfunktion und Signalwirkung in demselben Wachstumsprozess verbinden.','Connect meristem function and signaling in the same growth process.'),
 case('root-tip-reception','Ein zweiter gegebener Wurzelspitzenfall zeigt normale Signalbildung und intakte teilungsfähige Meristemzellen. In einer Empfängergruppe verhindert ein ausdrücklich lokal begrenzter Eingriff den Empfang des Signals; dort bleibt die normalerweise beobachtete Änderung der Teilungsrate aus. Eine Kontrollgruppe empfängt das Signal weiterhin. Erkläre die Befunde und warum sie nicht beweisen, dass sämtliche Meristeme aufgehört haben zu arbeiten.','A second supplied root tip case shows normal signal production and intact meristem cells capable of division. An explicitly local intervention prevents one receiving group from detecting the signal; the usual change in division rate is absent there. A control group still receives the signal. Explain the observations and why they do not establish that all meristems have stopped functioning.','Die lernende Person ordnet den Eingriff dem Empfangsschritt zu und erklärt die begrenzte Wachstumsregulation. Signalproduktion und grundsätzliche Teilungsfähigkeit werden nicht mit der ausgebliebenen lokalen Reaktion gleichgesetzt; keine universelle Wirkung aller zellulären Signalsysteme wird behauptet.','The learner assigns the intervention to reception and explains the bounded growth regulation. Signal production and basic capacity for division are not equated with the missing local response; no universal effect of all cellular signaling systems is claimed.','Frischer Transfer mit lokalem Eingriff und erhaltener Kontrolle.','Fresh transfer with a local intervention and preserved control.')]))
profiles.append(profile('experiment',[
 expect('experimental-performance','Experimentell untersuchen verlangt eine nachvollziehbare Frage, einen kontrollierten Aufbau, tatsächliche Durchführung und dokumentierte Beobachtungen. Ein fertiger Datensatz oder das Bild ersetzt Durchführung nicht. Bei allen drei Transportphänomenen müssen Vergleichsbedingungen und Störgrößen zur jeweiligen Frage passen.','Experimental investigation requires an explicit question, a controlled setup, actual performance and recorded observations. A finished dataset or the illustration does not substitute for performance. For all three transport phenomena, comparison conditions and confounders must fit the particular question.','Die lernende Person plant und führt mit bereitgestellten sicheren Verfahren Untersuchungen zu Diffusion, Osmose und Plasmolyse durch und dokumentiert ihr Vorgehen, Kontrollen und Ergebnisse.','The learner plans and performs diffusion, osmosis and plasmolysis investigations using supplied safe procedures and records methods, controls and results.'),
 expect('transport-results-limits','Diffusion bewirkt einen Nettostofftransport infolge eines Konzentrationsunterschieds; Osmose betrifft den Nettowassertransport über eine selektiv permeable Membran; Plasmolyse ist die beobachtbare Ablösung des Protoplasten von der Zellwand nach Wasserabgabe. Die Zellwand schrumpft dabei nicht mit dem Protoplasten. Beobachtung und modellgestützte Erklärung sind zu unterscheiden.','Diffusion produces net transport associated with a concentration difference; osmosis concerns net water movement across a selectively permeable membrane; plasmolysis is the observable separation of the protoplast from the cell wall after water loss. The wall does not shrink with the protoplast. Observation and model-supported explanation must be distinguished.','Die lernende Person deutet die eigenen dokumentierten Ergebnisse, trennt gemessenen Befund von Erklärung, berücksichtigt Abweichungen und zieht nur durch Kontrollen gestützte Schlussfolgerungen.','The learner interprets their own recorded results, separates observations from explanations, considers deviations and draws only conclusions supported by controls.')],
 [axis('materials-and-controls','Frische zugelassene Materialien, Vergleichskonzentrationen und Messzeitpunkte einsetzen.','Use fresh approved materials, comparison concentrations and measurement times.'),axis('measurement-representation','Farbausbreitung, Masse beziehungsweise Volumen und tatsächliche Mikroskopbeobachtung getrennt dokumentieren.','Record dye spread, mass or volume and actual microscopic observations separately.')],[
 case('perform-first-transport-suite','Mit einem bereitgestellten sicheren Schulverfahren untersuchst du einen Lebensmittelfarbstoff in unbewegtem Agar, Osmose an gleich behandelten Pflanzengewebestücken in zwei vorgegebenen Lösungen und Plasmolyse an einer geeigneten Epidermis unter dem Mikroskop. Formuliere Fragen und erwartete Unterschiede, plane faire Vergleichsbedingungen, führe alle drei Teile tatsächlich durch und protokolliere Zeiten, Beobachtungen und Abweichungen. Deute danach deine eigenen Ergebnisse mit Diffusion beziehungsweise Osmose und kennzeichne, was beobachtet und was erklärt ist.','Using a supplied safe classroom procedure, investigate food dye in still agar, osmosis in equivalently treated plant tissue pieces placed in two specified solutions, and plasmolysis in suitable epidermis under a microscope. State questions and expected differences, plan fair comparisons, actually perform all three parts and record times, observations and deviations. Then interpret your own results using diffusion or osmosis, distinguishing observations from explanations.','Ein nachvollziehbares echtes Durchführungsprotokoll aller drei Teile zeigt kontrollierte Materialien, Konzentrationen, Zeit und geeignete Mess- oder Beobachtungsverfahren. Die lernende Person deutet Farbausbreitung und Veränderungen der Gewebemasse sowie eine tatsächlich beobachtete Protoplastenablösung; ungeplante Strömung, Abtrocknung oder beschädigte Zellen werden als mögliche Grenzen benannt. Fehlt Durchführung, ist nur Interpretation gezeigt und dieses Erwartungsziel offen.','A verifiable actual performance record for all three parts shows controlled materials, concentrations, time and suitable measurements or observations. The learner interprets dye spread, tissue mass changes and actually observed protoplast separation; unintended flow, drying or damaged cells are identified as possible limitations. Without performance, only interpretation is demonstrated and the performance expectation remains open.','Versuchshandeln und Deutung am selben eigenen Untersuchungsverbund nachweisen.','Demonstrate experimental action and interpretation in the same personally performed investigation suite.'),
 case('fresh-replication-and-reversal','Untersuche mit demselben zugelassenen Verfahrensrahmen eine frische Variation: einen anders geformten Farbstoffbereich in Agar, neue Pflanzengewebestücke in einer geänderten Vergleichskonzentration und neue Epidermiszellen vor und nach Wechsel von Salzlösung zu Wasser. Begründe die Kontrollen, führe erneut alle drei Teile durch und dokumentiere tatsächliche Ergebnisse. Prüfe, ob und unter welchen Beobachtungsbedingungen Deplasmolyse sichtbar ist; setze eine nicht beobachtete Rückkehr nicht voraus.','Using the same approved procedural framework, investigate a fresh variation: a differently shaped dye region in agar, fresh plant tissue pieces at a changed comparison concentration and fresh epidermal cells before and after switching from salt solution to water. Justify controls, perform all three parts again and record actual outcomes. Examine whether and under which observed conditions deplasmolysis is visible; do not assume an unobserved reversal.','Der neue Durchführungsschritt ist unabhängig vom ersten Datensatz dokumentiert. Die lernende Person erklärt Unterschiede, Nettowassertransport und gegebenenfalls beobachtete Rückkehr des Protoplasten, ohne die Zellwand als permeable Membran auszugeben oder Zellschädigung auszuschließen. Ein fehlgeschlagener oder abweichender Versuch wird methodisch ausgewertet; erfundene ideale Befunde zählen nicht.','The fresh performance is documented independently of the first dataset. The learner explains differences, net water movement and any observed protoplast return without treating the wall as the selectively permeable membrane or excluding cell damage. Failed or deviating trials are evaluated methodologically; invented ideal observations do not count.','Frischer Ausführungs- und Erklärungstransfer mit Ergebnisoffenheit.','Fresh performance and explanation transfer with outcomes left open.')]))
profiles.append(profile('representation',[
 expect('membrane-model-comparison','Membranmodelle sind vereinfachte Darstellungen von Aufbau und möglichen Funktionen. Eine Lipiddoppelschicht mit außen anliegenden Proteinschichten und ein Modell mit eingelagerten Proteinen machen verschiedene Strukturannahmen. Fachliche Aussagekraft wird anhand passender Beobachtungen und Grenzen geprüft, nicht durch das modernere Aussehen allein.','Membrane models simplify structure and possible functions. A lipid bilayer with outer protein layers and a model with embedded proteins make different structural assumptions. Explanatory power is evaluated against relevant observations and limitations, not merely a more modern appearance.','Die lernende Person stellt zwei unterschiedliche Membranmodelle schematisch mit erklärter Zuordnung dar und prüft deren Aussagen anhand neuer Struktur- oder Beweglichkeitsbefunde.','The learner depicts two distinct membrane models schematically with justified structural assignments and tests their claims against fresh structural or mobility observations.')],
 [axis('structure-versus-motion','Befunde zu eingelagerten Proteinen und seitlicher Beweglichkeit gegenüberstellen.','Contrast evidence of embedded proteins and lateral mobility.'),axis('model-limit','Untersuchungsmethode und nicht sichtbare Eigenschaften ausdrücklich begrenzen.','Explicitly bound the measurement method and unobserved properties.')],[
 case('depict-protein-location-models','Dir werden zwei frische Modellbeschreibungen gegeben: A nimmt durchgängige Proteinschichten auf beiden Außenseiten einer Lipiddoppelschicht an; B enthält darin eingelagerte und teilweise durchspannende Proteine. Zeichne beide schematisch mit klarer Legende. Eine Untersuchung findet Proteinanteile im Inneren der Membran. Prüfe, welche Modellannahme besser zu diesem Befund passt und welche Aussage der einzelne Befund noch nicht trägt.','Two fresh model descriptions are supplied: A assumes continuous protein layers on both outer sides of a lipid bilayer; B includes embedded and partly spanning proteins. Draw both schematically with clear legends. An investigation finds protein regions inside the membrane. Evaluate which assumption fits this observation better and which claim this single observation does not establish.','Beide eigenen Schemata unterscheiden die Proteinlagen beziehungsweise Einlagerung und die Doppelschicht richtig. Der Befund stützt B gegenüber der durchgängigen äußeren Schichtannahme von A, beweist aber nicht alle Funktionen, Moleküldetails oder Beweglichkeitsannahmen. Die Darstellung bleibt ein Schema.','Both personally produced diagrams correctly distinguish protein layers versus embedding and the bilayer. The observation favors B over the continuous outer layer assumption of A but does not establish every function, molecular detail or mobility assumption. The drawing remains a schematic model.','Eigene Modelldarstellung mit begründeter Befundprüfung verbinden.','Connect personal model depiction with justified evidence evaluation.'),
 case('fresh-lateral-mobility','Ein zweiter Versuch verfolgt markierte Membranproteine: anfangs getrennte Markierungen verteilen sich später seitlich, während im beobachteten Zeitraum ein Teil an seinen Positionen bleibt. Stelle ein dazu passendes Membranmodell dar und prüfe die Behauptungen, alle Membranbestandteile seien starr und alle Proteine bewegten sich immer gleich frei.','A second investigation tracks marked membrane proteins: initially separated labels later redistribute laterally, while some remain at their positions during the observed interval. Depict a membrane model consistent with this evidence and evaluate the claims that all membrane components are fixed and that all proteins always move equally freely.','Die lernende Person stellt ein dynamisches Modell mit eingelagerter Proteinvielfalt dar und erklärt, dass der Befund starre Universalannahmen widerlegt, aber keine uneingeschränkte Beweglichkeit jedes Proteins belegt. Markierungen und Beobachtungszeit werden als Grenzen des Befunds genannt.','The learner depicts a dynamic model with diverse embedded proteins and explains that the observation counters a universal fixed arrangement but does not establish unrestricted mobility of every protein. Labels and observation time are identified as limits of the evidence.','Frischer Transfer von Strukturannahmen zur begrenzt belegten Dynamik.','Fresh transfer from structural assumptions to bounded evidence of dynamics.')]))
profiles.append(profile('procedure',[
 expect('bounded-rgt-calculation','Die RGT-Regel ist eine Näherung für einen angegebenen geeigneten Temperaturbereich bei sonst vergleichbaren Bedingungen. Der Q10-Faktor beschreibt die relative Geschwindigkeitsänderung pro 10 °C und ist nicht für alle Enzyme genau zwei. Mehrere 10-Grad-Schritte werden multiplikativ verknüpft.','The RGT rule approximates behavior within a specified suitable temperature interval under otherwise comparable conditions. The Q10 factor describes the relative rate change per 10 degrees Celsius and is not exactly two for every enzyme. Multiple ten-degree steps combine multiplicatively.','Die lernende Person berechnet für einen gegebenen gültigen Bereich Geschwindigkeitsänderungen aus einem angegebenen Faktor und deutet sie mit korrekten Einheiten beziehungsweise Verhältnissen.','The learner calculates rate changes from a supplied factor within a given valid interval and interprets them using correct units or ratios.'),
 expect('rgt-domain-limit','RGT-Hochrechnung außerhalb des gegebenen Bereichs ist ohne weitere Daten nicht begründet; Temperaturinaktivierung oder Denaturierung kann eine Aktivitätsabnahme verursachen. Die Temperatur allein beweist weder den genauen Inaktivierungsmechanismus noch eine universelle Denaturierungsschwelle.','RGT extrapolation outside the supplied interval is unsupported without further data; temperature inactivation or denaturation can reduce activity. Temperature alone establishes neither an exact inactivation mechanism nor a universal denaturation threshold.','Die lernende Person prüft anhand frischer Angaben oder Messwerte die Zulässigkeit einer Rechnung und trennt modellgestützte Vorhersage von begründet eingeschränkter Anwendung.','The learner checks whether a calculation is permitted by fresh conditions or measurements and distinguishes model-supported prediction from a justified application limit.')],
 [axis('temperature-steps','Ein bis zwei ganze Zehn-Grad-Schritte, Erwärmung und Abkühlung mit gegebenen Faktoren variieren.','Vary one or two whole ten-degree steps, heating and cooling with supplied factors.'),axis('stable-versus-inactivated','Geeigneten Modellbereich gegen materialgestützte Aktivitätsabnahme abgrenzen.','Distinguish an appropriate model interval from material-supported activity loss.')],[
 case('rgt-two-steps','Ein gegebener Enzymversuch hält pH, Enzym- und Substratbedingungen vergleichbar. Im ausdrücklich geprüften Bereich 10–30 °C gilt näherungsweise Q10=2; bei 10 °C beträgt die Anfangsgeschwindigkeit 3 Einheiten pro Minute. Berechne und deute die Vorhersagen für 20 und 30 °C sowie die Rückrechnung von 30 auf 10 °C. Ist eine gleiche Hochrechnung auf 60 °C damit schon begründet?','A supplied enzyme experiment keeps pH, enzyme and substrate conditions comparable. The explicitly tested interval is 10–30 degrees Celsius with approximate Q10=2; at 10 degrees the initial rate is 3 units per minute. Calculate and interpret predictions for 20 and 30 degrees and the reverse calculation from 30 to 10. Does this already justify the same extrapolation to 60 degrees?','Es ergeben sich 6 und 12 Einheiten pro Minute sowie rückwärts 12/4=3. Zwei Schritte multiplizieren zweimal; die relative Zunahme ist keine Addition von zwei Einheiten. 60 °C liegt außerhalb des belegten Bereichs, sodass keine fachliche Vorhersage daraus folgt.','The results are 6 and 12 units per minute and, in reverse, 12/4=3. Two steps multiply twice; relative increase is not an addition of two units. Sixty degrees is outside the established interval, so no valid prediction follows from this model alone.','Quantifizieren und Anwendungsbereich in derselben Rechnung prüfen.','Quantify and check the domain within the same calculation.'),
 case('fresh-rgt-factor-and-failure','Bei einem anderen gegebenen Enzym gilt nur zwischen 15 und 35 °C näherungsweise Q10=2,5; die Anfangsgeschwindigkeit bei 15 °C beträgt 4 Einheiten pro Minute. Berechne 25 und 35 °C. Nach einer gesonderten stärkeren Erhitzung misst man wieder bei 25 °C nur 1 Einheit pro Minute; Materialkontrollen belegen Temperaturinaktivierung. Vergleiche die Modellvorhersage mit dem Befund und erkläre, warum der Merksatz nicht beliebig weitergerechnet werden darf.','For a different supplied enzyme, approximate Q10=2.5 is valid only between 15 and 35 degrees Celsius; the initial rate at 15 degrees is 4 units per minute. Calculate rates at 25 and 35 degrees. After separate stronger heating, a measurement again at 25 degrees gives only 1 unit per minute; material controls establish temperature inactivation. Compare prediction and observation and explain why the rule cannot be extrapolated indefinitely.','Die gültigen Vorhersagen sind 10 und 25 Einheiten pro Minute. Die spätere Messung fällt trotz gleicher Messtemperatur darunter, weil die aktive Enzymmenge beziehungsweise funktionsfähige Struktur laut Material nicht erhalten blieb. Die lernende Person unterscheidet die Modellbedingungen von einer thermisch geschädigten Probe und nennt keine universelle Temperaturschwelle.','The valid predictions are 10 and 25 units per minute. The later measurement is lower despite the same measurement temperature because active enzyme amount or functional structure was not preserved according to the material. The learner distinguishes model conditions from a thermally damaged sample and gives no universal threshold temperature.','Frischer Faktor und kontrollierte Modellgrenze verhindern bloßen Formelabruf.','A fresh factor and controlled model limit prevent mere formula recall.')]))
profiles.append(profile('modeling',[
 expect('allosteric-mechanism-distinction','Allosterische Hemmung beschreibt im gegebenen Modell eine regulierende Bindung abseits des aktiven Zentrums und eine Änderung der Enzymwirkung. Nichtkompetitiv bezeichnet eine bestimmte Wirkung auf die Geschwindigkeitskurve; der Bindungsort allein bestimmt diese kinetische Einordnung nicht. Ein Schema beweist daher keine allgemeine Gleichsetzung.','Allosteric inhibition describes, in the supplied model, regulatory binding away from the active site and a change in enzyme action. Noncompetitive denotes a particular effect on the rate curve; binding location alone does not determine that kinetic classification. A diagram therefore does not establish a universal equivalence.','Die lernende Person erklärt ein gegebenes allosterisches Beispiel anhand von Bindung und Wirkung und unterscheidet diese Mechanismusbeschreibung von einer nur durch passende zusätzliche Befunde gestützten nichtkompetitiven Einordnung.','The learner explains a supplied allosteric example using binding and effect and distinguishes that mechanism description from a noncompetitive classification supported only by appropriate additional observations.'),
 expect('bounded-inhibitor-transfer','In einem ausdrücklich rein nichtkompetitiven Modell erreicht mehr Substrat die ursprüngliche maximale Reaktionsgeschwindigkeit nicht wieder. Diese Modellfolge darf nicht jedem andersartigen allosterischen System oder jedem Medikament zugeschrieben werden. Reversible Regulation ist nicht automatisch bleibende Denaturierung.','In an explicitly pure noncompetitive model, more substrate does not restore the original maximum rate. This model consequence must not be assigned to every other allosteric system or every medication. Reversible regulation is not automatically permanent denaturation.','Die lernende Person überträgt die gegebene Hemmungsregel auf einen neuen Alltags- oder Medikamentenmodellfall und benennt erforderliche Zusatzinformationen sowie Grenzen.','The learner transfers the supplied inhibition rule to a fresh everyday or medication model case and identifies required additional information and limitations.')],
 [axis('mechanism-and-data','Bindungsschema, zusätzliche Aktivitätsdaten und Entfernen eines Hemmstoffs unterscheiden.','Distinguish binding diagrams, additional activity data and removal of an inhibitor.'),axis('everyday-model','Materialgestützte Verdauungs- und Medikamentenmodelle ohne medizinische Handlungsempfehlung nutzen.','Use material-supported digestion and medication models without medical recommendations.')],[
 case('digestive-enzyme-side-site','In einem neuen schematischen Verdauungsenzymmodell bindet Stoff I laut Material an einer seitlichen Regulationsstelle und verändert die Form des aktiven Zentrums; die Reaktion wird langsamer. Nach Entfernen von I kehrt die ursprüngliche Aktivität zurück. Erkläre allosterische Hemmung und ihren Alltagsbezug. Kann allein dieses Bild schon beweisen, dass die Hemmung rein nichtkompetitiv ist?','In a fresh schematic digestive enzyme model, substance I binds a lateral regulatory site according to the material and changes active-site shape; the reaction slows. Original activity returns after I is removed. Explain allosteric inhibition and its everyday relevance. Can this image alone establish pure noncompetitive inhibition?','Die lernende Person erklärt die regulierende Bindung und Aktivitätsänderung sowie die beobachtete Rückkehr nach Entfernung. Das Schema zeigt einen Mechanismus, liefert aber keine ausreichende Geschwindigkeitskurve zur reinen nichtkompetitiven Einordnung. Sie behauptet weder bleibende Denaturierung noch eine Wirkung sämtlicher Nahrungsstoffe.','The learner explains regulatory binding, activity change and observed recovery after removal. The diagram shows a mechanism but lacks sufficient rate-curve evidence to classify pure noncompetitive inhibition. Neither permanent denaturation nor an effect of all food substances is claimed.','Allosterisches Beispiel erklären und aus einem Bild nicht zu viel folgern.','Explain an allosteric example and avoid overclaiming from a diagram.'),
 case('fresh-inhibitor-model-transfer','Ein fiktives Medikamentenmodell beschreibt Hemmstoff N ausdrücklich als rein nichtkompetitiv: unter sonst gleichen Bedingungen sinkt das Geschwindigkeitsplateau von 100 auf 50 Einheiten, und die Substratkonzentration bei jeweils halbem Plateau bleibt gleich. Mehr Substrat stellt das frühere Plateau nicht wieder her. Ein anderer Stoff A bindet ebenfalls außerhalb des aktiven Zentrums, aber seine Kurve ist nicht angegeben. Erkläre die Folgen für N, vergleiche die Beleglage für A und begrenze die Übertragung auf echte Medikamente.','A fictional medication model explicitly identifies inhibitor N as pure noncompetitive: under otherwise identical conditions the rate plateau falls from 100 to 50 units, while the substrate concentration at each half-plateau stays the same. More substrate does not restore the previous plateau. Another substance A also binds outside the active site, but its curve is not supplied. Explain the consequences for N, compare the evidence for A and bound transfer to real medicines.','Die lernende Person erklärt anhand der gegebenen Modelldaten die verminderte maximale Geschwindigkeit und dass zusätzliche Substratmenge die Hemmung hier nicht aufhebt. A ist wegen des Bindungsorts noch nicht als rein nichtkompetitiv belegt. Es wird keine allgemeine Wirkung, Dosierung oder Wirksamkeit echter Medikamente aus dem fiktiven Modell behauptet; fortgeschrittene kinetische Herleitungen sind nicht erforderlich.','The learner uses the supplied model data to explain the lowered maximum rate and why more substrate does not remove inhibition here. Binding location alone does not establish pure noncompetitive behavior for A. The fictional model establishes no general effect, dosage or effectiveness of real medicines; advanced kinetic derivations are not required.','Frischer Transfer mit expliziten Daten und einem unbestimmten Gegenfall.','Fresh transfer with explicit data and an undetermined comparison case.')]))
